style.css:
/* Plano de fundo inspirado no tema */
body {
    background: url('https://i.pinimg.com/736x/03/50/ba/0350ba5f8da153dda92df0ded9289dc5.jpgURL_DA_IMAGEM') no-repeat center center fixed;
    background-size: cover;
    color: #4B3621; /* Cor que combina com o tema */
}

/* Alterar cabeçalhos e botões */
h1, h2, h3, h4, h5, h6, button {
    font-family: 'Arial', sans-serif;
    color: #4B3621;
}

/* Ajustar caixas de texto e bordas */
input, textarea {
    border: 2px solid #E0CDA9;
    background-color: #FFF8E7;
    color: #4B3621;
}

/* Destaques */
a {
    color: #D1A774;
}
a:hover {
    color: #F4A261;
}
